changeSet.sql:
-- Propagate maker-checker enablement from padded duplicate -> clean twin UPDATE m_permission AS keep SET can_maker_checker = TRUE FROM m_permission AS drop_row WHERE TRIM(BOTH FROM drop_row.code) = keep.code AND drop_row.code <> keep.code AND keep.code = TRIM(BOTH FROM keep.code) AND drop_row.can_maker_checker IS TRUE AND keep.can_maker_checker IS NOT TRUE;
-- Re-point role grants from padded permission to clean twin INSERT INTO m_role_permission (role_id, permission_id) SELECT DISTINCT rp.role_id, keep.id FROM m_role_permission rp INNER JOIN m_permission drop_row ON drop_row.id = rp.permission_id INNER JOIN m_permission keep ON keep.code = TRIM(BOTH FROM drop_row.code) AND keep.id <> drop_row.id AND keep.code = TRIM(BOTH FROM keep.code) WHERE drop_row.code <> TRIM(BOTH FROM drop_row.code) AND NOT EXISTS ( SELECT 1 FROM m_role_permission existing WHERE existing.role_id = rp.role_id AND existing.permission_id = keep.id );
-- Drop role grants still pointing at padded twins DELETE FROM m_role_permission rp USING m_permission drop_row, m_permission keep WHERE rp.permission_id = drop_row.id AND drop_row.code <> TRIM(BOTH FROM drop_row.code) AND keep.code = TRIM(BOTH FROM drop_row.code) AND keep.id <> drop_row.id AND keep.code = TRIM(BOTH FROM keep.code);
-- Delete padded permissions that have a clean twin DELETE FROM m_permission drop_row USING m_permission keep WHERE drop_row.code <> TRIM(BOTH FROM drop_row.code) AND keep.code = TRIM(BOTH FROM drop_row.code) AND keep.id <> drop_row.id AND keep.code = TRIM(BOTH FROM keep.code);
-- Trim remaining padded-only permission rows (no clean twin) UPDATE m_permission SET code = TRIM(BOTH FROM code), entity_name = CASE WHEN entity_name IS NULL THEN NULL ELSE TRIM(BOTH FROM entity_name) END WHERE code <> TRIM(BOTH FROM code) OR (entity_name IS NOT NULL AND entity_name <> TRIM(BOTH FROM entity_name));

UPDATE m_workflow_definition
SET task_permission_code = TRIM(BOTH FROM task_permission_code)
WHERE task_permission_code <> TRIM(BOTH FROM task_permission_code);

-- Propagate maker-checker enablement from padded duplicate -> clean twin UPDATE m_permission keep INNER JOIN m_permission drop_row ON TRIM(BOTH FROM drop_row.code) = keep.code AND drop_row.code <> keep.code AND keep.code = TRIM(BOTH FROM keep.code) SET keep.can_maker_checker = 1 WHERE drop_row.can_maker_checker = 1 AND IFNULL(keep.can_maker_checker, 0) <> 1;
-- Re-point role grants from padded permission to clean twin INSERT INTO m_role_permission (role_id, permission_id) SELECT DISTINCT rp.role_id, keep.id FROM m_role_permission rp INNER JOIN m_permission drop_row ON drop_row.id = rp.permission_id INNER JOIN m_permission keep ON keep.code = TRIM(BOTH FROM drop_row.code) AND keep.id <> drop_row.id AND keep.code = TRIM(BOTH FROM keep.code) WHERE drop_row.code <> TRIM(BOTH FROM drop_row.code) AND NOT EXISTS ( SELECT 1 FROM m_role_permission existing WHERE existing.role_id = rp.role_id AND existing.permission_id = keep.id );
-- Drop role grants still pointing at padded twins DELETE rp FROM m_role_permission rp INNER JOIN m_permission drop_row ON drop_row.id = rp.permission_id INNER JOIN m_permission keep ON keep.code = TRIM(BOTH FROM drop_row.code) AND keep.id <> drop_row.id AND keep.code = TRIM(BOTH FROM keep.code) WHERE drop_row.code <> TRIM(BOTH FROM drop_row.code);
-- Delete padded permissions that have a clean twin DELETE drop_row FROM m_permission drop_row INNER JOIN m_permission keep ON keep.code = TRIM(BOTH FROM drop_row.code) AND keep.id <> drop_row.id AND keep.code = TRIM(BOTH FROM keep.code) WHERE drop_row.code <> TRIM(BOTH FROM drop_row.code);
-- Trim remaining padded-only permission rows (no clean twin) UPDATE m_permission SET code = TRIM(BOTH FROM code), entity_name = CASE WHEN entity_name IS NULL THEN NULL ELSE TRIM(BOTH FROM entity_name) END WHERE code <> TRIM(BOTH FROM code) OR (entity_name IS NOT NULL AND entity_name <> TRIM(BOTH FROM entity_name));

UPDATE m_workflow_definition
SET task_permission_code = TRIM(BOTH FROM task_permission_code)
WHERE task_permission_code <> TRIM(BOTH FROM task_permission_code);
